public class SettingsForm : Form {
 MainForm main;Snapshot original;Tabs tabs=new Tabs();Dictionary<string,Panel> pages=new Dictionary<string,Panel>();
 TextBox device;TextBox[] antNames=new TextBox[8];Label[] antSummary=new Label[8];Fields[] masks=new Fields[8];Dictionary<int,TextBox[]> bands=new Dictionary<int,TextBox[]>();ComboBox[] serial=new ComboBox[2],ant=new ComboBox[2],ptt=new ComboBox[2];Label discoveryStatus;
 ComboBox language,inband;CheckBox dhcp,protection;TextBox ip,netmask,gateway;ConnectionControls connection;Button apply,save,cancel;bool committing;List<Form> children=new List<Form>();
 public SettingsForm(MainForm owner){main=owner;original=main.AG.Config;UI.Form(this,"AG 4O3A | Definições",new Size(650,594));tabs.SetBounds(8,8,634,540);Controls.Add(tabs);
  foreach(string key in new[]{"Início","Rede","FlexRadio","Antenas","Bandas","Saída","BCD","P2P","Stack","Avançadas","Sobre"}){var tab=new TabPage{BackColor=UI.Page};Lang.Bind(tab,key);tabs.TabPages.Add(tab);var panel=new Panel{BackColor=UI.Page};panel.SetBounds(60,4,494,500);tab.Controls.Add(panel);tab.Resize+=delegate{panel.Left=Math.Max(0,(tab.ClientSize.Width-panel.Width)/2);};pages[key]=panel;if(key!="FlexRadio")UI.Head(panel,key);}
  BuildHome();BuildBands();BuildAntennas();BuildFlex();BuildNetwork();BuildAdvanced();BuildAbout();BuildStack();BuildOutputs();foreach(string kind in new[]{"BCD","P2P"})BuildDiagram(kind);
  apply=UI.Button(this,"Aplicar",302,556,106);save=UI.Button(this,"Guardar",416,556,106);save.BackColor=UI.Header;save.ForeColor=Color.White;cancel=UI.Button(this,"Cancelar",530,556,106);apply.Click+=async delegate{await Commit(false);};save.Click+=async delegate{await Commit(true);};cancel.Click+=delegate{Close();};CancelButton=cancel;
  Action translateChoices=delegate{foreach(var box in serial){int selected=box.SelectedIndex;var none=box.Items.Cast<RadioChoice>().FirstOrDefault(c=>c.Serial=="");if(none!=null){none.Name=Lang.T("Nenhum equipamento");box.SelectedIndex=-1;box.SelectedIndex=selected;}}};Lang.Changed+=translateChoices;Disposed+=delegate{Lang.Changed-=translateChoices;};Positions.Attach(this,"settings");FormClosing+=delegate(object sender,FormClosingEventArgs e){if(committing&&!main.IsDisposed)e.Cancel=true;};FormClosed+=delegate{foreach(var child in children.ToArray())if(!child.IsDisposed)child.Close();};
 }
 void BuildHome(){var p=pages["Início"];UI.Label(p,"Nome do equipamento:",16,42);device=UI.Text(p,original.Conf.Get("name").Replace('_',' '),16,72);UI.Label(p,"Firmware: "+original.Info.Get("v")+"  |  Hardware: "+original.Info.Get("hw"),16,124);UI.Label(p,"Série: "+original.Info.Get("serial"),16,158);var flags=new AGLanguageFlags{AccessibleName="Português / Español / English"};flags.SetBounds(16,214,104,24);p.Controls.Add(flags);language=UI.Combo(p,new[]{"Português","Español","English"},new[]{"Português","Español","English"}[Array.IndexOf(new[]{"pt","es","en"},Lang.Code)],16,244,280);language.SelectedIndexChanged+=delegate{try{Lang.Set(new[]{"pt","es","en"}[language.SelectedIndex]);main.Render();}catch(Exception ex){UI.Error(this,ex);}};}
 void BuildBands(){var p=pages["Bandas"];UI.Label(p,"Nome da banda:",34,34,150);UI.Label(p,"Intervalo de frequência (MHz):",190,34,304);foreach(var b in original.Bands){int id=b.Int("id"),y=60+id*25;if(id>0)UI.Label(p,id.ToString(),4,y,26);var fields=new[]{UI.Text(p,b.Get("name").Replace('_',' '),34,y,150),UI.Text(p,b.Get("freq_start"),190,y,148),UI.Text(p,b.Get("freq_stop"),344,y,148)};foreach(var f in fields){f.ReadOnly=id==0;f.Font=new Font("Segoe UI Semibold",9);}bands[id]=fields;fields[0].TextChanged+=delegate{RefreshSummaries();};}}
 void BuildAntennas(){var p=pages["Antenas"];UI.Label(p,"Nome:",16,38,170);UI.Label(p,"Bandas:",196,38,260);for(int i=0;i<8;i++){int index=i;var a=original.Antennas.First(x=>x.Int("id")==i+1);antNames[i]=UI.Text(p,a.Get("name").Replace('_',' '),16,74+i*38,172);masks[i]=new Fields{{"rx",a.Get("rx")},{"tx",a.Get("tx")}};antSummary[i]=UI.Label(p,"",196,74+i*38,240,26);antSummary[i].BorderStyle=BorderStyle.FixedSingle;antSummary[i].AutoEllipsis=true;var button=new AGChecklistButton();button.SetBounds(438,72+i*38,54,30);p.Controls.Add(button);button.Click+=delegate{ChooseBands(index);};}RefreshSummaries();}
 void RefreshSummaries(){for(int i=0;i<8;i++){if(antSummary[i]==null||masks[i]==null)continue;int mask=Convert.ToInt32(masks[i]["rx"],16)|Convert.ToInt32(masks[i]["tx"],16);antSummary[i].Text=string.Join(" ",bands.Where(b=>(mask&(1<<b.Key))!=0).OrderBy(b=>b.Key).Select(b=>b.Value[0].Text));if(antSummary[i].Text=="")antSummary[i].Text="None";antSummary[i].ForeColor=antSummary[i].Text=="None"?Color.Green:Color.DarkOrange;}}
 void ChooseBands(int index){using(var d=new Form()){UI.Form(d,"Bandas",new Size(360,520));d.Text=Lang.T("Bandas")+" | "+antNames[index].Text;UI.Label(d,"Banda",16,8,160);UI.Label(d,"RX",200,8,50);UI.Label(d,"TX",270,8,50);var rx=new CheckBox[16];var tx=new CheckBox[16];for(int id=0;id<16;id++){UI.Label(d,bands[id][0].Text,16,38+id*26,170);rx[id]=UI.Check(d,"",(Convert.ToInt32(masks[index]["rx"],16)&(1<<id))!=0,200,38+id*26,40);tx[id]=UI.Check(d,"",(Convert.ToInt32(masks[index]["tx"],16)&(1<<id))!=0,270,38+id*26,40);}var ok=UI.Button(d,"Guardar",140,474,100);ok.DialogResult=DialogResult.OK;var no=UI.Button(d,"Cancelar",250,474,100);no.DialogResult=DialogResult.Cancel;d.CancelButton=no;Positions.Attach(d,"antenna-bands");if(d.ShowDialog(this)==DialogResult.OK){int r=0,t=0;for(int b=0;b<16;b++){if(rx[b].Checked)r|=1<<b;if(tx[b].Checked)t|=1<<b;}masks[index]["rx"]=r.ToString("X4");masks[index]["tx"]=t.ToString("X4");RefreshSummaries();}}}
 class RadioChoice {public string Serial,Name;public override string ToString(){return Name;}}
 void Choices(ComboBox box,string value,string[] rows){box.Items.Clear();box.Items.Add(new RadioChoice{Serial="",Name=Lang.T("Nenhum equipamento")});foreach(var row in rows){var f=Fields.Parse(row);string s=f.Get("serial");if(s==""||box.Items.Cast<RadioChoice>().Any(c=>c.Serial==s))continue;box.Items.Add(new RadioChoice{Serial=s,Name=f.Get("model")+" / "+f.Get("nickname").Replace('_',' ')+" | "+s});}if(value!=""&&!box.Items.Cast<RadioChoice>().Any(c=>c.Serial==value))box.Items.Add(new RadioChoice{Serial=value,Name=value});box.SelectedItem=box.Items.Cast<RadioChoice>().First(c=>c.Serial==value);}
 string Serial(int p){var c=serial[p].SelectedItem as RadioChoice;return c==null?"":c.Serial;}
 void BuildFlex(){var p=pages["FlexRadio"];for(int i=0;i<2;i++){int y=i*190;var f=original.Flex[i];UI.Head(p,"FlexRadio | Porta "+(i==0?"A":"B"),y);UI.Label(p,"Equipamento / número de série:",16,y+40);serial[i]=UI.Combo(p,new string[0],"",16,y+68,364);serial[i].DropDownWidth=540;Choices(serial[i],f.Get("serial"),new string[0]);var find=UI.Button(p,"Procurar",388,y+66,102,30);find.Click+=async delegate{await Discover();};UI.Label(p,"Antena:",16,y+108,70);ant[i]=UI.Combo(p,new[]{"ANT1","ANT2","XVRT"},f.Get("ant"),90,y+106,110);UI.Label(p,"PTT:",245,y+108,45);ptt[i]=UI.Combo(p,new[]{"LAN","RCA"},f.Get("ptt"),300,y+106,110);}discoveryStatus=UI.Label(p,"",16,398,470,70);Shown+=async delegate{if(!Program.Test)await Discover();};}
 async Task Discover(){string[] rows=new string[0];if(Program.Demo)return;if(await main.Run(()=>rows=main.AG.Command("flex list"))){for(int i=0;i<2;i++)Choices(serial[i],Serial(i),rows);discoveryStatus.Text=rows.Length==0?Lang.T("Nenhum rádio detetado. A seleção atual foi mantida."):rows.Length+" "+Lang.T("equipamento(s) encontrado(s).");}}
 void BuildNetwork(){var p=pages["Rede"];p.Controls[0].Dispose();UI.Head(p,"Local");dhcp=UI.Check(p,"Automático (DHCP)",original.Network.Get("dhcp")=="1",140,34,320);UI.Label(p,"Endereço IP",16,80);ip=UI.Text(p,original.Network.Get("address"),16,106);UI.Label(p,"Máscara de rede",16,140);netmask=UI.Text(p,original.Network.Get("netmask"),16,166);UI.Label(p,"Gateway",16,200);gateway=UI.Text(p,original.Network.Get("gateway"),16,226);UI.Label(p,"Alterar a rede reinicia o equipamento ao guardar.",16,262,465,24);connection=new ConnectionControls(p,main.Profile,288,true);Action enabled=delegate{dhcp.Enabled=connection.Local.Checked;ip.Enabled=netmask.Enabled=gateway.Enabled=connection.Local.Checked&&!dhcp.Checked;};dhcp.CheckedChanged+=delegate{enabled();};connection.Local.CheckedChanged+=delegate{enabled();};enabled();}
 void BuildStack(){var p=pages["Stack"];UI.Check(p,"Ativar Stack (16 × 2)",original.Stack.Get("in_use")=="1",16,46).Enabled=false;UI.Label(p,"Número de série do AG:",16,100);UI.Combo(p,new[]{original.Stack.Get("serial")},original.Stack.Get("serial"),16,130,450).Enabled=false;UI.Label(p,"Tipo de comutação:",16,186);UI.Combo(p,new[]{"Comutadores A/B externos","Utilizar portas 7 e 8"},original.Stack.Get("mode")=="1"?"Utilizar portas 7 e 8":"Comutadores A/B externos",16,216,450).Enabled=false;UI.Label(p,"Preparado para um segundo Antenna Genius. Ativação ainda indisponível nesta versão.",16,284,450,72);}
 void BuildOutputs(){var p=pages["Saída"];UI.Label(p,"Organize os relés em grupos de saída.",16,48,450,46);var b=UI.Button(p,"Abrir editor de relés",16,112,280,36);b.Click+=delegate{OpenChild("outputs",()=>new OutputForm(original));};UI.Label(p,"Preparado para utilização futura. A configuração dos relés mantém-se no utilitário original.",16,184,450,80);}
 void BuildDiagram(string kind){var p=pages[kind];var drawing=new AGConnectorDiagram{P2P=kind=="P2P",Language=Lang.Code,Cursor=Cursors.Hand};drawing.SetBounds(8,36,478,402);p.Controls.Add(drawing);Action update=delegate{drawing.Language=Lang.Code;};Lang.Changed+=update;drawing.Disposed+=delegate{Lang.Changed-=update;};Action show=delegate{OpenChild(kind,delegate{var f=new Form();UI.Form(f,kind,new Size(900,760));f.FormBorderStyle=FormBorderStyle.Sizable;f.MinimumSize=new Size(450,400);var d=new AGConnectorDiagram{P2P=kind=="P2P",Language=Lang.Code,Dock=DockStyle.Fill};f.Controls.Add(d);Action u=delegate{d.Language=Lang.Code;};Lang.Changed+=u;f.Disposed+=delegate{Lang.Changed-=u;};return f;});};drawing.Click+=delegate{show();};UI.Button(p,"Ampliar esquema",150,450,194,30).Click+=delegate{show();};}
 void OpenChild(string key,Func<Form> create){var old=children.FirstOrDefault(candidate=>!candidate.IsDisposed&&candidate.Name==key);if(old!=null){if(old.WindowState==FormWindowState.Minimized)old.WindowState=FormWindowState.Normal;old.Activate();return;}var f=create();f.Name=key;children.Add(f);Positions.Attach(f,key=="outputs"?"output-designer":key.ToLower()+"-reference");f.Show();}
void BuildAbout(){var p=pages["Sobre"];string[] text={"Antena Genius 4O3A","Versão "+Program.Version+" | Windows","Ligação Local/Remota","Desenvolvido por Eduardo Arraia - CT7ASY","Software de distribuição gratuita."};int[] y={48,88,130,182,226};for(int i=0;i<text.Length;i++){var l=UI.Label(p,text[i],20,y[i],452,36);l.TextAlign=ContentAlignment.MiddleCenter;l.Font=new Font("Segoe UI Semibold",i==0?14:11);}var update=UI.Button(p,"Verificar atualizações",131,290,230,34);update.Font=new Font("Segoe UI Semibold",11);update.Click+=async delegate{await main.CheckUpdates(true);};var web=UI.Button(p,"Visitar 4O3A",131,342,230,34);web.Font=new Font("Segoe UI Semibold",11);web.Click+=delegate{try{Process.Start(new ProcessStartInfo("https://4o3a.com/"){UseShellExecute=true});}catch(Exception ex){UI.Error(this,ex);}};}
 void BuildAdvanced(){var p=pages["Avançadas"];UI.Label(p,"Porta Inband:",16,42);inband=UI.Combo(p,new[]{"None","A","B"},new[]{"None","A","B"}[original.Conf.Int("inband_port")],16,72);protection=UI.Check(p,"Proteção de banda",original.Conf.Get("bandcheck")=="1",16,120);protection.Enabled=original.Conf.ContainsKey("bandcheck");UI.Label(p,"Impede a utilização da mesma banda nas portas A e B em simultâneo.",16,152,450,48);UI.Button(p,"Exportar configuração",16,212,250,34).Click+=delegate{Export();};UI.Button(p,"Importar configuração",16,256,250,34).Click+=delegate{Import();};UI.Label(p,"Ficheiros AG 4O3A: antenas, bandas, FlexRadio e opções. Não incluem rede, Stack, relés ou palavras-passe.",16,310,450,86);UI.Button(p,"Reiniciar",16,440,140,36).Click+=async delegate{await Maintenance(false);};UI.Button(p,"Repor definições de fábrica",220,440,258,36).Click+=async delegate{await Maintenance(true);};}
 public Snapshot Draft(){var s=new Snapshot();s.Conf=new Fields{{"name",Validation.Name(device.Text)},{"inband_port",inband.SelectedIndex.ToString()},{"bandcheck",protection.Checked?"1":"0"}};for(int i=0;i<8;i++)s.Antennas.Add(new Fields{{"id",(i+1).ToString()},{"name",Validation.Name(antNames[i].Text)},{"rx",masks[i]["rx"]},{"tx",masks[i]["tx"]}});foreach(int id in bands.Keys.OrderBy(x=>x)){var b=bands[id];s.Bands.Add(new Fields{{"id",id.ToString()},{"name",Validation.Name(b[0].Text)},{"freq_start",Validation.Frequency(b[1].Text)},{"freq_stop",Validation.Frequency(b[2].Text)}});}for(int i=0;i<2;i++)s.Flex.Add(new Fields{{"id",(i+1).ToString()},{"serial",Serial(i)},{"ant",ant[i].Text},{"ptt",ptt[i].Text}});Configuration.Validate(s);return s;}
 async Task Commit(bool close){if(committing||main.Busy)return;try{Snapshot draft=Draft();Profile profile=connection.Read();bool reconnect=profile.Mode!=main.Profile.Mode||profile.LocalHost!=main.Profile.LocalHost||profile.LocalPort!=main.Profile.LocalPort||profile.RemoteHost!=main.Profile.RemoteHost||profile.RemotePort!=main.Profile.RemotePort||profile.PasswordProtected!=main.Profile.PasswordProtected;string network=connection.Local.Checked?Validation.Network(original.Network,dhcp.Checked,ip.Text,netmask.Text,gateway.Text):null;var commands=Configuration.Commands(original,draft);bool useDhcp=dhcp.Checked;string localAddress=ip.Text.Trim();committing=true;tabs.Enabled=apply.Enabled=save.Enabled=cancel.Enabled=false;bool ok=await main.Run(()=>{if(Program.Demo){draft.Info=original.Info;draft.Network=original.Network;draft.Stack=original.Stack;main.AG.Config=draft;return;}main.AG.Apply(commands);if(network!=null){main.AG.Guard();try{main.AG.Command(network);}catch{main.AG.Dispose();throw new Exception("A rede não confirmou a alteração; o equipamento pode ter reiniciado. Verifique o IP antes de voltar a guardar.");}if(!useDhcp)profile.LocalHost=localAddress;}profile.Save();main.Profile=profile;if(network!=null){main.AG.Dispose();main.Follow.Dispose();main.Status="Equipamento a reiniciar. Volte a ligar nas definições.";}else {if(reconnect){main.Follow.Dispose();main.AG.Connect(profile);}main.Follow.Reset(main.AG.Config);main.Status=profile.Mode+" | "+profile.Address+":"+profile.Port;}});if(ok){original=main.AG.Config;if(!Program.Demo)connection.Original=main.Profile.Copy();Lang.Bind(this,"AG 4O3A | Definições - Aplicado");committing=false;if(network!=null||close)Close();}}catch(Exception ex){UI.Error(this,ex);}finally{committing=false;if(!IsDisposed)tabs.Enabled=apply.Enabled=save.Enabled=cancel.Enabled=true;}}
 void Export(){using(var d=new SaveFileDialog{Filter="AG 4O3A (*.json)|*.json",FileName="AG4O3A-configuracao.json"})if(d.ShowDialog(this)==DialogResult.OK)try{File.WriteAllText(d.FileName,Configuration.Export(Draft()));}catch(Exception ex){UI.Error(this,ex);}}
 void Import(){using(var d=new OpenFileDialog{Filter="AG 4O3A (*.json)|*.json"})if(d.ShowDialog(this)==DialogResult.OK)try{if(new FileInfo(d.FileName).Length>1048576)throw new Exception("Ficheiro demasiado grande.");Snapshot s=Configuration.Import(File.ReadAllText(d.FileName));if(MessageBox.Show(this,"Substituir os campos atuais? Reveja as alterações antes de Aplicar ou Guardar.",Lang.T("Importar configuração"),MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;device.Text=s.Conf.Get("name").Replace('_',' ');inband.SelectedIndex=s.Conf.Int("inband_port");protection.Checked=s.Conf.Get("bandcheck")=="1";foreach(var a in s.Antennas){int i=a.Int("id")-1;antNames[i].Text=a.Get("name").Replace('_',' ');masks[i]["rx"]=a.Get("rx");masks[i]["tx"]=a.Get("tx");}foreach(var b in s.Bands){if(b.Int("id")==0)continue;var fields=bands[b.Int("id")];fields[0].Text=b.Get("name").Replace('_',' ');fields[1].Text=b.Get("freq_start");fields[2].Text=b.Get("freq_stop");}for(int i=0;i<2;i++){Choices(serial[i],s.Flex[i].Get("serial"),new string[0]);ant[i].SelectedItem=s.Flex[i].Get("ant");ptt[i].SelectedItem=s.Flex[i].Get("ptt");}RefreshSummaries();}catch(Exception ex){UI.Error(this,ex);}}
 async Task Maintenance(bool reset){if(Program.Test||Program.Demo||main.Busy)return;string message=reset?"Repor as definições de fábrica? A configuração, incluindo a rede, será apagada e o equipamento reiniciará.":"Reiniciar o Antenna Genius agora? A ligação será interrompida.";if(MessageBox.Show(this,message,"AG 4O3A",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;committing=true;tabs.Enabled=apply.Enabled=save.Enabled=cancel.Enabled=false;try{await main.Run(()=>{main.AG.Guard();try{main.AG.Command(reset?"conf init":"reboot");}finally{main.AG.Dispose();main.Follow.Dispose();main.Status="Verifique o equipamento e volte a ligar nas definições.";}});}finally{committing=false;Close();}}
 public void CapturePages(string folder){if(Configuration.Commands(original,Draft()).Count!=0)throw new Exception("Unchanged form generated device writes");for(int i=0;i<tabs.TabPages.Count;i++){tabs.SelectedIndex=i;UI.Capture(this,Path.Combine(folder,"settings-"+i+".png"));}}
 public void CaptureLanguages(string folder){for(int l=0;l<3;l++){language.SelectedIndex=l;string path=Path.Combine(folder,new[]{"pt","es","en"}[l]);Directory.CreateDirectory(path);CapturePages(path);}language.SelectedIndex=0;}
}
public class OutputForm : Form {
 public OutputForm(Snapshot s){UI.Form(this,"Editor de relés de saída",new Size(650,500));var list=new ListBox{DisplayMember="Text"};list.SetBounds(16,84,164,352);Controls.Add(list);UI.Label(this,"Grupos de saída",16,16,164);UI.Button(this,"+",16,48,40).Enabled=false;var detail=UI.Label(this,"Ainda não existem grupos configurados.",208,140,422,220);detail.TextAlign=ContentAlignment.MiddleCenter;foreach(string row in s.Groups){var f=Fields.Parse(row);if(f.Get("in_use")=="1")list.Items.Add(new Group{Text=f.Get("name").Replace('_',' '),Row=row});}list.SelectedIndexChanged+=delegate{var item=list.SelectedItem as Group;if(item==null)return;detail.Text=item.Text+Environment.NewLine+item.Row;};UI.Label(this,"Editor preparado. A criação e a edição de grupos ficam disponíveis numa próxima versão.",16,450,618,46);}
 class Group {public string Text{get;set;}public string Row;}
}
